const s = 1000;
const m = s * 60;
const h = m * 60;
const d = h * 24;
const w = d * 7;
const y = d * 365.25;
const mo = y / 12;

const UNITS = {
	y, yr: y, yrs: y, year: y, years: y,
	mo, month: mo, months: mo,
	w, week: w, weeks: w,
	d, day: d, days: d,
	h, hr: h, hrs: h, hour: h, hours: h,
	m, min: m, mins: m, minute: m, minutes: m,
	s, sec: s, secs: s, second: s, seconds: s,
	ms: 1, msec: 1, msecs: 1, millisecond: 1, milliseconds: 1,
};

// [size in ms, short suffix, long name], largest first.
const SCALES = [
	[y, 'y', 'year'],
	[mo, 'mo', 'month'],
	[w, 'w', 'week'],
	[d, 'd', 'day'],
	[h, 'h', 'hour'],
	[m, 'm', 'minute'],
	[s, 's', 'second'],
];

export function parse(str) {
	if (typeof str !== 'string' || str.length === 0 || str.length > 100) {
		throw new Error('Value provided to ms.parse() must be a string with length between 1 and 100');
	}

	const match = /^(-?\d*\.?\d+) *(milliseconds?|msecs?|ms|seconds?|secs?|s|minutes?|mins?|m|hours?|hrs?|h|days?|d|weeks?|w|months?|mo|years?|yrs?|y)?$/i.exec(str);
	if (!match) {
		return Number.NaN;
	}

	return parseFloat(match[1]) * UNITS[(match[2] || 'ms').toLowerCase()];
}

function formatDuration(ms, long) {
	const abs = Math.abs(ms);
	for (const [size, short, name] of SCALES) {
		if (abs >= size) {
			const count = Math.round(ms / size);
			if (!long) {
				return `${count}${short}`;
			}

			return `${count} ${name}${abs >= size * 1.5 ? 's' : ''}`;
		}
	}

	return long ? `${ms} ms` : `${ms}ms`;
}

export function format(ms, options) {
	if (typeof ms !== 'number' || !Number.isFinite(ms)) {
		throw new Error('Value provided to ms.format() must be of type number.');
	}

	return formatDuration(ms, Boolean(options && options.long));
}

export default function ms(value, options) {
	if (typeof value === 'string') {
		return parse(value);
	}

	if (typeof value === 'number') {
		return format(value, options);
	}

	throw new Error('Value provided to ms() must be a string or number.');
}

