import ms from './ms.js';

export function main() {
	const args = process.argv.slice(2);

	if (args.includes('--help')) {
		console.log('Usage: ms [--long] <value>...');
		process.exit(0);
	}

	if (args.length === 0) {
		console.error('Usage: ms [--long] <value>...');
		process.exit(1);
	}

	const long = args.includes('--long');
	let failed = false;

	for (const arg of args.filter(a => a !== '--long')) {
		const input = /^-?\d+$/.test(arg) ? Number(arg) : arg;
		try {
			const result = ms(input, {long});
			if (typeof result === 'number' && Number.isNaN(result)) {
				console.error(`Invalid duration: ${arg}`);
				failed = true;
			} else {
				console.log(result);
			}
		} catch (error) {
			console.error(error.message);
			failed = true;
		}
	}

	process.exit(failed ? 1 : 0);
}

if (import.meta.main) {
	main();
}

