import {expect, test} from 'bun:test';
import ms, {format, parse} from '../src/ms.js';

test('parse', () => {
	expect(parse('2h')).toBe(7200000);
	expect(Number.isNaN(parse('nope'))).toBe(true);
});

test('format', () => {
	expect(format(7200000)).toBe('2h');
	expect(format(7200000, {long: true})).toBe('2 hours');
});

test('default export', () => {
	expect(ms('1s')).toBe(1000);
	expect(ms(1000)).toBe('1s');
});
